package com.thymeandtable.service;
import com.thymeandtable.db.DatabaseConnection; import com.thymeandtable.model.*; import java.sql.*; import java.util.*;
public class RecipeService {
 public static final double PANTRY_WEIGHT=.50, RATING_WEIGHT=.20, INFLUENCER_WEIGHT=.30;
 public List<Recipe> list(String search,String tag)throws SQLException{List<Recipe> out=new ArrayList<>();String sql="SELECT r.id,r.title,r.description,r.instructions,r.category,r.tags,COALESCE(ip.display_name,u.username,'Community') creator,r.influencer_score,AVG(rv.rating) avg_rating FROM recipes r LEFT JOIN users u ON u.id=r.owner_id LEFT JOIN influencer_profiles ip ON ip.user_id=u.id LEFT JOIN recipe_reviews rv ON rv.recipe_id=r.id WHERE (?='' OR r.title LIKE ? OR r.description LIKE ? OR EXISTS(SELECT 1 FROM recipe_ingredients ri JOIN ingredients i ON i.id=ri.ingredient_id WHERE ri.recipe_id=r.id AND i.name LIKE ?)) AND (?='' OR r.tags LIKE '%'||?||'%') GROUP BY r.id ORDER BY r.title";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){String q=search==null?"":search.trim();String t=tag==null?"":tag.trim();p.setString(1,q);p.setString(2,"%"+q+"%");p.setString(3,"%"+q+"%");p.setString(4,"%"+q+"%");p.setString(5,t);p.setString(6,t);try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}return out;}
 public Recipe get(int id)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT r.id,r.title,r.description,r.instructions,r.category,r.tags,COALESCE(ip.display_name,u.username,'Community') creator,r.influencer_score,AVG(rv.rating) avg_rating FROM recipes r LEFT JOIN users u ON u.id=r.owner_id LEFT JOIN influencer_profiles ip ON ip.user_id=u.id LEFT JOIN recipe_reviews rv ON rv.recipe_id=r.id WHERE r.id=? GROUP BY r.id")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 private Recipe map(ResultSet r)throws SQLException{double rating=r.getDouble("avg_rating");Double avg=r.wasNull()?null:rating;return new Recipe(r.getInt("id"),r.getString("title"),r.getString("description"),r.getString("instructions"),r.getString("category"),r.getString("tags"),r.getString("creator"),r.getDouble("influencer_score"),avg);}
 public List<String[]> ingredients(int id)throws SQLException{List<String[]> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT i.name,ri.required_quantity,ri.unit FROM recipe_ingredients ri JOIN ingredients i ON i.id=ri.ingredient_id WHERE ri.recipe_id=? ORDER BY i.name")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),Double.toString(r.getDouble(2)),r.getString(3)});}}return out;}
 public Map<String,Double> pantry(User u)throws SQLException{Map<String,Double> m=new HashMap<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT lower(i.name),pi.quantity FROM pantry_items pi JOIN ingredients i ON i.id=pi.ingredient_id WHERE pi.user_id=?")){p.setInt(1,u.getId());try(ResultSet r=p.executeQuery()){while(r.next())m.put(r.getString(1),r.getDouble(2));}}return m;}
 public List<Recipe> recommendations(User u)throws SQLException{List<Recipe> all=list("","");Map<String,Double> stock=pantry(u);Map<Integer,Double> scores=new HashMap<>();for(Recipe r:all){List<String[]> req=ingredients(r.getId());if(req.isEmpty())continue;double total=0,covered=0;for(String[] x:req){double need=Double.parseDouble(x[1]);total+=need;covered+=Math.min(need,stock.getOrDefault(x[0].toLowerCase(Locale.ROOT),0.0));}double match=total==0?0:100*covered/total;double rating=r.getAverageRating()==null?50:r.getAverageRating()*20;double influencer=r.getInfluencerScore()*20;double score=PANTRY_WEIGHT*match+RATING_WEIGHT*rating+INFLUENCER_WEIGHT*influencer;scores.put(r.getId(),score);}all.removeIf(r->!scores.containsKey(r.getId()));all.sort((a,b)->{int cmp=Double.compare(scores.get(b.getId()),scores.get(a.getId()));return cmp!=0?cmp:a.getTitle().compareToIgnoreCase(b.getTitle());});return all;}
 public List<String[]> reviews(int id)throws SQLException{List<String[]> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT u.username,rv.rating,rv.review_text,rv.created_at FROM recipe_reviews rv JOIN users u ON u.id=rv.user_id WHERE rv.recipe_id=? ORDER BY rv.created_at DESC")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4)});}}return out;}
 public String review(User u,int id,int rating,String text)throws SQLException{if(u.isAdmin()||u.isInfluencer())return "Only regular users can submit recipe ratings in this project.";if(rating<1||rating>5)return "Choose a rating from 1 to 5.";if(text!=null&&text.length()>1000)return "Review must be under 1000 characters.";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO recipe_reviews(recipe_id,user_id,rating,review_text) VALUES(?,?,?,?) ON CONFLICT(recipe_id,user_id) DO UPDATE SET rating=excluded.rating,review_text=excluded.review_text,created_at=CURRENT_TIMESTAMP")){p.setInt(1,id);p.setInt(2,u.getId());p.setInt(3,rating);p.setString(4,text==null?"":text.trim());p.executeUpdate();return "";}}
 public String add(User u,String title,String desc,String instructions,String category,String tags,String ingredientLines)throws SQLException{if(!(u.isInfluencer()||u.isAdmin()))return "Only influencers or admins can publish recipes.";if(title==null||title.trim().length()<3||title.length()>100)return "Recipe title must be 3–100 characters.";if(desc==null||desc.trim().isEmpty()||instructions==null||instructions.trim().isEmpty())return "Description and instructions are required.";String[] lines=ingredientLines.split("\r?\n");if(lines.length==0)return "Add at least one ingredient as Name,quantity,unit per line.";try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO recipes(owner_id,title,description,instructions,category,tags,influencer_score) VALUES(?,?,?,?,?,?,3.0)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,u.getId());p.setString(2,title.trim());p.setString(3,desc.trim());p.setString(4,instructions.trim());p.setString(5,category==null?"Other":category.trim());p.setString(6,tags==null?"":tags.trim());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getInt(1);}}int count=0;for(String line:lines){if(line.isBlank())continue;String[] x=line.split(",");if(x.length!=3)throw new IllegalArgumentException("Each ingredient must be Name,quantity,unit.");String name=x[0].trim(),unit=x[2].trim();double qty=Double.parseDouble(x[1].trim());if(name.isEmpty()||unit.isEmpty()||qty<=0||qty>100000)throw new IllegalArgumentException("Ingredient quantity must be positive and values valid.");try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO ingredients(name,unit) VALUES(?,?)")){p.setString(1,name);p.setString(2,unit);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO recipe_ingredients(recipe_id,ingredient_id,required_quantity,unit) VALUES(?,(SELECT id FROM ingredients WHERE name=?),?,?)")){p.setInt(1,id);p.setString(2,name);p.setDouble(3,qty);p.setString(4,unit);p.executeUpdate();}count++;}if(count==0)throw new IllegalArgumentException("Add at least one valid ingredient.");c.commit();return "";}catch(Exception e){c.rollback();if(e instanceof IllegalArgumentException)return e.getMessage();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public String update(User u,int id,String title,String desc,String instructions,String category,String tags,String ingredientLines)throws SQLException{if(!(u.isInfluencer()||u.isAdmin()))return "Only influencers or admins can edit recipes.";if(title==null||title.trim().length()<3||title.length()>100)return "Recipe title must be 3–100 characters.";if(desc==null||desc.trim().isEmpty()||instructions==null||instructions.trim().isEmpty())return "Description and instructions are required.";try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement check=c.prepareStatement("SELECT owner_id FROM recipes WHERE id=?")){check.setInt(1,id);try(ResultSet r=check.executeQuery()){if(!r.next()){c.rollback();return "Recipe not found.";}if(!u.isAdmin()&&r.getInt(1)!=u.getId()){c.rollback();return "You can edit only your own recipes.";}}}try(PreparedStatement p=c.prepareStatement("UPDATE recipes SET title=?,description=?,instructions=?,category=?,tags=? WHERE id=?")){p.setString(1,title.trim());p.setString(2,desc.trim());p.setString(3,instructions.trim());p.setString(4,category==null?"Other":category.trim());p.setString(5,tags==null?"":tags.trim());p.setInt(6,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("DELETE FROM recipe_ingredients WHERE recipe_id=?")){p.setInt(1,id);p.executeUpdate();}int count=0;for(String line:ingredientLines.split("\\r?\\n")){if(line.isBlank())continue;String[] x=line.split(",");if(x.length!=3)throw new IllegalArgumentException("Each ingredient must be Name,quantity,unit.");String name=x[0].trim(),unit=x[2].trim();double qty=Double.parseDouble(x[1].trim());if(name.isEmpty()||unit.isEmpty()||qty<=0||qty>100000)throw new IllegalArgumentException("Ingredient quantity must be positive and values valid.");try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO ingredients(name,unit) VALUES(?,?)")){p.setString(1,name);p.setString(2,unit);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO recipe_ingredients(recipe_id,ingredient_id,required_quantity,unit) VALUES(?,(SELECT id FROM ingredients WHERE name=?),?,?)")){p.setInt(1,id);p.setString(2,name);p.setDouble(3,qty);p.setString(4,unit);p.executeUpdate();}count++;}if(count==0)throw new IllegalArgumentException("Add at least one valid ingredient.");c.commit();return "";}catch(Exception e){c.rollback();if(e instanceof IllegalArgumentException)return e.getMessage();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public String delete(User u,int id)throws SQLException{if(!u.isAdmin()){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM recipes WHERE id=? AND owner_id=?")){p.setInt(1,id);p.setInt(2,u.getId());if(p.executeUpdate()==0)return "You can delete only your own recipes.";return "";}}try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM recipes WHERE id=?")){p.setInt(1,id);p.executeUpdate();return "";}}
 public List<String[]> influencers()throws SQLException{List<String[]> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT u.id,ip.display_name,ip.bio,ip.speciality,COUNT(DISTINCT r.id) recipe_count,AVG(rv.rating) avg_rating FROM influencer_profiles ip JOIN users u ON u.id=ip.user_id LEFT JOIN recipes r ON r.owner_id=u.id LEFT JOIN recipe_reviews rv ON rv.recipe_id=r.id GROUP BY u.id ORDER BY ip.display_name")){try(ResultSet r=p.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)});}}return out;}
 public List<String[]> influencerRecipes(int userId)throws SQLException{List<String[]> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,title,category,tags FROM recipes WHERE owner_id=? ORDER BY title")){p.setInt(1,userId);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4)});}}return out;}
}
